/**
 * Emits the seed half of the editable-content migration from
 * lib/content/defaults.ts.
 *
 *   node scripts/generate-content-seed.mjs
 *
 * Writes the statements between the @generated-seed markers in
 * supabase/migrations/20260830140000_editable_content.sql, in place.
 *
 * The seed is generated rather than hand-written because it is a copy of forty
 * settings, seven headings, twenty-six services and thirty-two image URLs.
 * Transcribed by hand, any of those would eventually disagree with the
 * defaults the site falls back to, and the disagreement would surface only as
 * a section that changes when the database happens to be reachable —
 * approximately the worst bug shape there is. Generating it makes the two the
 * same data by construction.
 *
 * Every statement upserts on the row's stable id, so re-running the migration
 * refreshes the seeded rows without duplicating them and without touching any
 * row an editor has added.
 *
 * Reads the defaults through a small parse of the TypeScript module rather
 * than importing it, because the module is TypeScript behind a path alias and
 * this script runs under plain node. See `loadDefaults`.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const MIGRATION = join(root, "supabase/migrations/20260830140000_editable_content.sql");
const START = "-- @generated-seed-start";
const END = "-- @generated-seed-end";

/**
 * Reads lib/content/defaults.ts by slicing out the object literal and
 * evaluating it.
 *
 * The alternative — adding a TypeScript loader to devDependencies purely to
 * run one build script — is a heavier dependency than the problem deserves.
 * This works because the module is deliberately a single plain object literal
 * with no computed values, no imports used inside it and no functions; it
 * throws rather than silently misreading if that ever stops being true.
 */
function loadDefaults() {
  const source = readFileSync(join(root, "lib/content/defaults.ts"), "utf8");

  const start = source.indexOf("export const defaultContent");
  if (start === -1) throw new Error("defaults.ts no longer exports defaultContent");

  const literalStart = source.indexOf("{", start);
  const literalEnd = source.lastIndexOf("};");
  if (literalStart === -1 || literalEnd === -1) {
    throw new Error("could not find the defaultContent object literal");
  }

  const literal = source.slice(literalStart, literalEnd + 1);
  // eslint-disable-next-line no-new-func
  return new Function(`return ${literal}`)();
}

/** Single-quoted SQL literal; doubles any embedded quote. */
const q = (value) => `'${String(value).replace(/'/g, "''")}'`;
const nullable = (value) => (value === null || value === undefined ? "NULL" : q(value));

function upsert(table, columns, rows, conflictColumn = "id") {
  if (rows.length === 0) return "";

  const updates = columns
    .filter((column) => column !== conflictColumn)
    .map((column) => `${column} = EXCLUDED.${column}`)
    .join(",\n    ");

  const values = rows
    .map((row) => `  (${columns.map((column) => row[column]).join(", ")})`)
    .join(",\n");

  return [
    `INSERT INTO public.${table} (${columns.join(", ")}) VALUES`,
    values,
    `ON CONFLICT (${conflictColumn}) DO UPDATE SET`,
    `    ${updates};`,
    "",
  ].join("\n");
}

const content = loadDefaults();
const listed = (row) => ({ id: q(row.id), sort_order: row.sort_order });
const out = [];

out.push("-- Generated by scripts/generate-content-seed.mjs — do not edit by hand.");
out.push("-- Re-run it after changing lib/content/defaults.ts.");
out.push("");

out.push(
  upsert(
    "site_settings",
    ["key", "value"],
    Object.entries(content.settings).map(([key, value]) => ({ key: q(key), value: q(value) })),
    "key"
  )
);

out.push(
  upsert(
    "section_headings",
    ["section", "eyebrow", "title", "subtitle"],
    Object.values(content.headings).map((h) => ({
      section: q(h.section),
      eyebrow: q(h.eyebrow),
      title: q(h.title),
      subtitle: nullable(h.subtitle),
    })),
    "section"
  )
);

out.push(
  upsert("service_groups", ["id", "slug", "label", "sort_order"],
    content.serviceGroups.map((r) => ({ ...listed(r), slug: q(r.slug), label: q(r.label) })))
);

out.push(
  upsert("services", ["id", "group_slug", "icon", "title", "description", "sort_order"],
    content.services.map((r) => ({
      ...listed(r), group_slug: q(r.group_slug), icon: q(r.icon),
      title: q(r.title), description: q(r.description),
    })))
);

out.push(
  upsert("about_features", ["id", "icon", "title", "description", "sort_order"],
    content.aboutFeatures.map((r) => ({
      ...listed(r), icon: q(r.icon), title: q(r.title), description: q(r.description),
    })))
);

out.push(
  upsert("about_stats", ["id", "value", "label", "sort_order"],
    content.aboutStats.map((r) => ({ ...listed(r), value: q(r.value), label: q(r.label) })))
);

out.push(
  upsert("process_steps", ["id", "icon", "title", "description", "sort_order"],
    content.processSteps.map((r) => ({
      ...listed(r), icon: q(r.icon), title: q(r.title), description: q(r.description),
    })))
);

out.push(
  upsert("stats", ["id", "emoji", "target", "suffix", "label", "sort_order"],
    content.stats.map((r) => ({
      ...listed(r), emoji: q(r.emoji), target: r.target, suffix: q(r.suffix), label: q(r.label),
    })))
);

out.push(
  upsert("faqs", ["id", "question", "answer", "sort_order"],
    content.faqs.map((r) => ({ ...listed(r), question: q(r.question), answer: q(r.answer) })))
);

out.push(
  upsert("design_categories", ["id", "slug", "label", "sort_order"],
    content.designCategories.map((r) => ({ ...listed(r), slug: q(r.slug), label: q(r.label) })))
);

out.push(
  upsert("design_images", ["id", "category_slug", "image_url", "sort_order"],
    content.designImages.map((r) => ({
      ...listed(r), category_slug: q(r.category_slug), image_url: q(r.image_url),
    })))
);

out.push(
  upsert("before_after", ["id", "title", "before_image", "after_image", "sort_order"],
    content.beforeAfter.map((r) => ({
      ...listed(r), title: q(r.title),
      before_image: q(r.before_image), after_image: q(r.after_image),
    })))
);

out.push(
  upsert("service_options", ["id", "label", "sort_order"],
    content.serviceOptions.map((r) => ({ ...listed(r), label: q(r.label) })))
);

out.push(
  upsert("footer_services", ["id", "label", "sort_order"],
    content.footerServices.map((r) => ({ ...listed(r), label: q(r.label) })))
);

out.push(
  upsert("hero_clients", ["id", "name", "sort_order"],
    content.heroClients.map((r) => ({ ...listed(r), name: q(r.name) })))
);

const seed = out.join("\n").replace(/\n+$/, "\n");

const migration = readFileSync(MIGRATION, "utf8");
const startAt = migration.indexOf(START);
const endAt = migration.indexOf(END);
if (startAt === -1 || endAt === -1) {
  throw new Error(`${MIGRATION} is missing the @generated-seed markers`);
}

writeFileSync(
  MIGRATION,
  migration.slice(0, startAt) + START + "\n" + seed + END + migration.slice(endAt + END.length),
  "utf8"
);

console.log(`seeded ${MIGRATION}`);
